import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('tempo_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text);}catch{}walk(v);return v;}
const rows=[];for(const tool of ['liveTempoPreview','liveTempoPreviewAsync','liveTempoApply','liveTempoApplyAsync','liveTransactionRelease']){const valid=tool.includes('Preview')?{tempo:124}:tool.includes('Apply')?{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'}:{transactionIds:['missing','batch_missing']};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,0,19,20,124,999,1000,'','x'])cases.push({...valid,[key]:value});}for(const args of cases){const host=new McpHost(new DeterministicLiveSimulator());let result;try{result=clean(await host[tool](1,args));}catch(e){result={error:e.message};}rows.push({tool,args,result});}}
const workflows=[];
for(const async of [false,true])for(const scenario of ['normal','expire','epoch','tempo-edit','identity-edit','apply-before','apply-after','apply-cancel','apply-refusal','apply-no-effect','apply-read','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-tempo','undo-prior-tempo','undo-other-set']){
const sim=new DeterministicLiveSimulator(), calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;
function faultError(){return fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):new Error(fault.endsWith('cancel')?'operation cancelled before dispatch':'injected operation failure');}
function invoke(i,c){calls.push(clean({invocation:i,context:c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(c&&cache.has(key))return cache.get(key);if(!fired&&['before','cancel','refusal'].some(s=>fault.endsWith(s))){fired=true;throw faultError();}const noEffect=!fired&&fault.endsWith('no-effect');let result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;if(c&&!noEffect)cache.set(key,result);afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw faultError();}return result;}
function get(r){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='undo-current-read')){fired=true;throw new Error('injected authoritative read failure');}return sim.get(r);}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get,invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:(c,r)=>sim.snapshotAsync(c,r),discoverAsync:(r,c)=>sim.discoverAsync(r,c),getAsync:async r=>get(r),invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async()=>sim.status()};const host=new McpHost(adapter),results=[];const suffix=async?'Async':'';const preview=await host['liveTempoPreview'+suffix](1,{tempo:124});results.push(clean(preview));const txid=JSON.parse(preview.result.content[0].text).transactionId;const record=host.transactions.get(txid);const states=[];
async function perform(kind,key){const args={transactionId:txid,confirmation:kind,idempotencyKey:key};let outcome;try{outcome=kind==='apply'?await host['liveTempoApply'+suffix](results.length+1,args):await host[async?'liveUndoAsync':'liveUndo'](results.length+1,args);}catch(e){outcome={error:e.message};}results.push(clean(outcome));states.push(clean(record));}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='tempo-edit')sim.state.set.tempo=130;if(scenario==='identity-edit')sim.state.set.objectIdentity='other:set';
if(scenario.startsWith('apply-'))fault=scenario;await perform('apply','apply-key');await perform('apply','other-key');await perform('apply','apply-key');fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-tempo')sim.state.set.tempo=130;if(scenario==='undo-prior-tempo')sim.state.set.tempo=120;if(scenario==='undo-other-set')sim.state.set.objectIdentity='other:set';if(scenario.startsWith('undo-')&&!scenario.includes('tempo')&&!scenario.includes('set'))fault=scenario;
await perform('undo','undo-key');await perform('undo','other-undo-key');await perform('undo','undo-key');fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key');
results.push(clean(host.liveTransactionRelease(results.length+1,{transactionIds:[txid,txid,'missing','batch_missing']})));
workflows.push({async,scenario,results,states,calls,tempo:sim.state.set.tempo});}
fs.writeFileSync(new URL('host-tempo-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
